// === Tab: FlowardRotion ===
function setup() {
	createCanvas(windowWidth, windowHeight);
}

function draw() {
	noStroke()
	smooth()
	for (j =0; j < 256 ; j ++) {
		cj = cos(millis()*j/5000000)
		sj = sin(millis()*j/5000000)
		push();
		background(128+sj*255, 128+cj*127, 128+sj*cj*sq(j), 0)
		translate(width/2,height/2)
		scale(sj*cj*2.4)
		rotate(j/2)
		fill(128+cj*255, 128+sj*j, 128+sj*j^255,255)
		ellipse((sq(j)*sj)*0.005, (sq(j)*cj)*0.005, j/19.2)
		pop();
	}
}

